  def __init__(self):
    self.root = TrieNode()
    self.keyToVal = {}

  def insert(self, key: str, val: int) -> None:
    diff = val - self.keyToVal.get(key, 0)
    node: TrieNode = self.root
    for c in key:
      if c not in node.children:
        node.children[c] = TrieNode()
      node = node.children[c]
      node.sum += diff
    self.keyToVal[key] = val

